const campusVideo=document.querySelector('#campus-video');const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');if(reducedMotion.matches)campusVideo.pause();else campusVideo.play().catch(()=>{});reducedMotion.addEventListener('change',e=>{if(e.matches)campusVideo.pause()});dialog.addEventListener('close',()=>{if(dialog.classList.contains('film-dialog')){dialog.classList.remove('film-dialog');document.querySelector('#dialog-content').innerHTML=''}});
new IntersectionObserver(([entry])=>document.body.classList.toggle('hero-in-view',entry.isIntersecting),{threshold:0.15}).observe(document.querySelector('.hero-film'));
